const [submitting, setSubmitting] = useState(false);
const [submitted, setSubmitted] = useState(false);
const [submitError, setSubmitError] = useState(false);
The submitting state indicates whether the submission is in progress, the
submitted state indicates whether the form has been submitted, and the
submitError state indicates whether the submission failed.
